def clean(df):
    df = df.copy()
    # fix island variant Bisco -> Biscoe
    if 'island' in df.columns:
        df['island'] = df['island'].replace({'Bisco': 'Biscoe'})
        # strip whitespace if any
        mask = df['island'].notna()
        df.loc[mask, 'island'] = df.loc[mask, 'island'].astype(str).str.strip()
    # fix sex whitespace variant "female " -> "female"
    if 'sex' in df.columns:
        mask = df['sex'].notna()
        df.loc[mask, 'sex'] = df.loc[mask, 'sex'].astype(str).str.strip()
        df['sex'] = df['sex'].replace({'': pd.NA, 'nan': pd.NA})
    # ensure numeric columns are numeric (text_number)
    for col in ['body_mass_g', 'flipper_length_mm', 'bill_length_mm', 'bill_depth_mm', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # drop exact duplicate rows (penguin_id is unique id)
    df = df.drop_duplicates()
    return df

def answer(df):
    df = clean(df)
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    grouped = df.groupby('species', dropna=True)['body_mass_g'].sum()
    result = {}
    for k, v in grouped.items():
        if pd.isna(k):
            continue
        # convert to int if integer-like
        fv = float(v)
        if fv.is_integer():
            result[str(k)] = int(fv)
        else:
            result[str(k)] = fv
    return result
